SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS stores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, address VARCHAR(255), phone VARCHAR(30), is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30), password VARCHAR(255) NOT NULL, role ENUM('ADMIN','EMPLOYEE') NOT NULL DEFAULT 'EMPLOYEE', permissions LONGTEXT, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_stores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, store_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_store(user_id,store_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(store_id) REFERENCES stores(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, name VARCHAR(150) NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, sku VARCHAR(100) NOT NULL UNIQUE, barcode VARCHAR(100) NULL, name VARCHAR(255) NOT NULL, cost_price DECIMAL(15,2) NOT NULL DEFAULT 0.00, selling_price DECIMAL(15,2) NOT NULL DEFAULT 0.00, brand VARCHAR(100) NULL, image_url TEXT NULL, description TEXT, allow_discount TINYINT(1) NOT NULL DEFAULT 1, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_product_search(name,sku,barcode), INDEX idx_product_brand(brand), FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS inventories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, store_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_inventory(store_id,product_id), FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_code VARCHAR(50) NOT NULL UNIQUE, store_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, subtotal DECIMAL(15,2) NOT NULL, discount_amount DECIMAL(15,2) NOT NULL DEFAULT 0, total_amount DECIMAL(15,2) NOT NULL, status ENUM('COMPLETED','CANCELLED') NOT NULL DEFAULT 'COMPLETED', cancel_reason TEXT, cancelled_by BIGINT UNSIGNED NULL, cancelled_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_order_date(store_id,created_at), FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(cancelled_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, sku_snapshot VARCHAR(100) NOT NULL, product_name_snapshot VARCHAR(255) NOT NULL, unit_price DECIMAL(15,2) NOT NULL, quantity INT NOT NULL, discount_amount DECIMAL(15,2) NOT NULL DEFAULT 0, serial_number VARCHAR(120), imei VARCHAR(120), total_amount DECIMAL(15,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method ENUM('CASH','BANK_TRANSFER','CARD') NOT NULL, amount DECIMAL(15,2) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS returns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, return_code VARCHAR(50) NOT NULL UNIQUE, order_id BIGINT UNSIGNED NOT NULL, store_id BIGINT UNSIGNED NOT NULL, created_by BIGINT UNSIGNED NOT NULL, status ENUM('COMPLETED') NOT NULL DEFAULT 'COMPLETED', reason TEXT NOT NULL, total_amount DECIMAL(15,2) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS return_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, return_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, amount DECIMAL(15,2) NOT NULL, serial_number VARCHAR(120), imei VARCHAR(120), FOREIGN KEY(return_id) REFERENCES returns(id), FOREIGN KEY(order_item_id) REFERENCES order_items(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS return_exchange_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, return_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(15,2) NOT NULL, total_amount DECIMAL(15,2) NOT NULL, FOREIGN KEY(return_id) REFERENCES returns(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS stock_transfers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_code VARCHAR(50) NOT NULL UNIQUE, from_store_id BIGINT UNSIGNED NOT NULL, to_store_id BIGINT UNSIGNED NOT NULL, requested_by BIGINT UNSIGNED NOT NULL, approved_by BIGINT UNSIGNED NULL, status ENUM('REQUESTED','REJECTED','COMPLETED') NOT NULL DEFAULT 'REQUESTED', request_note TEXT, reject_reason TEXT, requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_at DATETIME NULL, FOREIGN KEY(from_store_id) REFERENCES stores(id), FOREIGN KEY(to_store_id) REFERENCES stores(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS stock_transfer_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, FOREIGN KEY(transfer_id) REFERENCES stock_transfers(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS stock_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, store_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, movement_type ENUM('INITIAL_IMPORT','SALE','RETURN','TRANSFER_OUT','TRANSFER_IN','MANUAL_ADJUSTMENT','CANCEL_ORDER_REVERSAL') NOT NULL, quantity_change INT NOT NULL, quantity_before INT NOT NULL, quantity_after INT NOT NULL, reference_type VARCHAR(50), reference_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, reason TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ledger_product(store_id,product_id,created_at), FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS repair_cases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_code VARCHAR(50) NOT NULL UNIQUE, store_id BIGINT UNSIGNED NOT NULL, technician_id BIGINT UNSIGNED NULL, customer_name VARCHAR(150) NOT NULL, customer_phone VARCHAR(30) NOT NULL, device_name VARCHAR(190) NOT NULL, imei VARCHAR(120), device_condition TEXT, repair_request TEXT NOT NULL, staff_note TEXT NULL, fee DECIMAL(15,2) NOT NULL DEFAULT 0.00, status ENUM('RECEIVED','INSPECTING','REPAIRING','WAITING_PARTS','COMPLETED','WAITING_PICKUP','RETURNED') NOT NULL DEFAULT 'RECEIVED', received_at DATETIME NOT NULL, expected_return_at DATETIME NULL, completed_at DATETIME NULL, returned_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, file_path VARCHAR(255) NOT NULL, original_name VARCHAR(255), file_size INT NOT NULL, mime_type VARCHAR(80) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, entity_type VARCHAR(50), entity_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, old_data LONGTEXT, new_data LONGTEXT, ip_address VARCHAR(64), description TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_date(created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS mail_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, to_email VARCHAR(190) NOT NULL, subject VARCHAR(255) NOT NULL, driver VARCHAR(30) NOT NULL DEFAULT 'smtp', status ENUM('SUCCESS','FAILED') NOT NULL DEFAULT 'SUCCESS', error_message TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_mail_date(created_at), INDEX idx_mail_status(status), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, store_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, type VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, link_type VARCHAR(50) NULL, link_id VARCHAR(100) NULL, severity ENUM('INFO','WARNING','DANGER','SUCCESS') NOT NULL DEFAULT 'INFO', is_read TINYINT(1) NOT NULL DEFAULT 0, read_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_notif_user(user_id,is_read,created_at), INDEX idx_notif_store(store_id,created_at), INDEX idx_notif_date(created_at), FOREIGN KEY(store_id) REFERENCES stores(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS push_subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, store_id BIGINT UNSIGNED NULL, endpoint TEXT NOT NULL, p256dh VARCHAR(255) NOT NULL, auth VARCHAR(255) NOT NULL, user_agent VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_push_user(user_id), INDEX idx_push_store(store_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_remember_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, user_agent VARCHAR(255) NULL, ip_address VARCHAR(64) NULL, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_user_tokens(user_id, expires_at), INDEX idx_token_hash(token_hash), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, config_key VARCHAR(150) NOT NULL UNIQUE, config_value LONGTEXT, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

